import math

def get_divisors(n):
    divs = set()
    for i in range(1, int(math.sqrt(n)) + 1):
        if n % i == 0:
            divs.add(i)
            divs.add(n // i)
    return sorted(list(divs))

def tau(n):
    divs = get_divisors(n)
    return len(divs)

def solve_search(N_limit):
    matching_tau = set()

    print(f"Starting search up to N = {N_limit}")

    for n in range(1, N_limit + 1):
        t = tau(n)

        if 5 <= t <= 15:
            divisors = get_divisors(n)

            # We already know t >= 5, so divisors must have at least 5 elements
            if len(divisors) >= 5:
                # a = 2nd smallest divisor (index 1)
                # b = 3rd smallest divisor (index 2)
                # c = 5th smallest divisor (index 4)
                a = divisors[1]
                b = divisors[2]
                c = divisors[4]

                # Check the condition: ab + ac + bc = n
                condition = a*b + a*c + b*c

                if condition == n:
                    matching_tau.add(t)
                    print(f"Found solution for N={n}, tau(N)={t}. Divisors: {divisors}. Check: {a}*{b} + {a}*{c} + {b}*{c} = {condition}")

    return sorted(list(matching_tau))

# Based on initial analysis, setting a limit of 50000 should be sufficient for a quick search.
N_LIMIT = 50000
result_taus = solve_search(N_LIMIT)
print(f"\nFinal result: {result_taus}")
